# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">RASYONEL SAYILARLA ÇOK ADIMLI İŞLEMLER VE PROBLEMLER</text>\n  <rect x="30" y="50" width="200" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İşlem Önceliği Sırası</text>\n  <text x="45" y="105" font-size="11.5" fill="#334155">1. Üslü ifadeler (a/b)ⁿ</text>\n  <text x="45" y="130" font-size="11.5" fill="#334155">2. Parantez içi işlemler</text>\n  <text x="45" y="155" font-size="11.5" fill="#334155">3. Çarpma ve bölme (soldan)</text>\n  <text x="45" y="180" font-size="11.5" fill="#334155">4. Toplama ve çıkarma</text>\n  <text x="130" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Ana kesir çizgisi yön belirler!</text>\n  <rect x="250" y="50" width="200" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Merdivenli İşlemler</text>\n  <text x="350" y="105" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">1 + 1 / (1 + 1/2)</text>\n  <text x="350" y="135" text-anchor="middle" font-size="11.5" fill="#334155">En alt basamaktan başlanır:</text>\n  <text x="350" y="160" text-anchor="middle" font-size="11.5" fill="#334155">1 + 1/2 = 3/2</text>\n  <text x="350" y="185" text-anchor="middle" font-size="11.5" fill="#334155">1 / (3/2) = 2/3</text>\n  <text x="350" y="212" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Sonuç: 1 + 2/3 = 5/3</text>\n  <rect x="470" y="50" width="200" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Problem Çözüm Adımları</text>\n  <text x="485" y="105" font-size="11.5" fill="#334155">• Bütünün kesir kadarı: Çarp</text>\n  <text x="485" y="130" font-size="11.5" fill="#334155">• Kesri verilen bütün: Böl</text>\n  <text x="485" y="155" font-size="11.5" fill="#334155">• &quot;Kalanın&quot; ifadelerinde</text>\n  <text x="495" y="175" font-size="11" fill="#475569">önce kalan kesir bulunur.</text>\n  <text x="570" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Ondalıklar kesre çevrilebilir</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÜÇ BOYUTLU CİSİMLERİN FARKLI YÖNLERDEN İKİ BOYUTLU GÖRÜNÜMLERİ</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Birim Küp Yapıları ve Bakış Yönleri</text>\n  <text x="55" y="105" font-size="11.5" fill="#334155">• Üstten Görünüm: Taban yerleşim planını verir.</text>\n  <text x="55" y="130" font-size="11.5" fill="#334155">• Önden ve Arkadan Görünüm: Birbirinin</text>\n  <text x="68" y="148" font-size="11" fill="#475569">dikey eksene göre simetriğidir (ayna görüntüsü).</text>\n  <text x="55" y="175" font-size="11.5" fill="#334155">• Sağdan ve Soldan Görünüm: Birbirinin</text>\n  <text x="68" y="193" font-size="11" fill="#475569">yatayda simetriği olan karesel bölgelerdir.</text>\n  <text x="185" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Derinlik farkı 2B görünümü değiştirmez!</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Örnek: L Biçimli 4 Birim Küplük Yapı</text>\n  <rect x="405" y="105" width="30" height="30" fill="#86efac" stroke="#15803d" stroke-width="1.5"/>\n  <rect x="405" y="135" width="30" height="30" fill="#86efac" stroke="#15803d" stroke-width="1.5"/>\n  <rect x="435" y="135" width="30" height="30" fill="#86efac" stroke="#15803d" stroke-width="1.5"/>\n  <text x="435" y="185" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Önden Görünüm</text>\n  <rect x="565" y="105" width="30" height="30" fill="#bbf7d0" stroke="#15803d" stroke-width="1.5"/>\n  <rect x="565" y="135" width="30" height="30" fill="#bbf7d0" stroke="#15803d" stroke-width="1.5"/>\n  <rect x="535" y="135" width="30" height="30" fill="#bbf7d0" stroke="#15803d" stroke-width="1.5"/>\n  <text x="565" y="185" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Arkadan Görünüm</text>\n  <text x="515" y="215" text-anchor="middle" font-size="11" fill="#334155">Sağ-Sol yer değiştirerek simetri oluşur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KAT PLANI (KODLANMIŞ ÜST GÖRÜNÜM) İLE YAPI OLUŞTURMA</text>\n  <rect x="40" y="55" width="270" height="175" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="175" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Sayısal Kat Planı (Üstten)</text>\n  <rect x="115" y="95" width="40" height="40" fill="#fee2e2" stroke="#b91c1c"/>\n  <text x="135" y="120" text-anchor="middle" font-size="15" font-weight="bold" fill="#991b1b">3</text>\n  <rect x="155" y="95" width="40" height="40" fill="#fee2e2" stroke="#b91c1c"/>\n  <text x="175" y="120" text-anchor="middle" font-size="15" font-weight="bold" fill="#991b1b">2</text>\n  <rect x="115" y="135" width="40" height="40" fill="#fee2e2" stroke="#b91c1c"/>\n  <text x="135" y="160" text-anchor="middle" font-size="15" font-weight="bold" fill="#991b1b">1</text>\n  <rect x="155" y="135" width="40" height="40" fill="#fee2e2" stroke="#b91c1c"/>\n  <text x="175" y="160" text-anchor="middle" font-size="15" font-weight="bold" fill="#991b1b">1</text>\n  <text x="175" y="205" text-anchor="middle" font-size="11.5" fill="#334155">Sayılar o sütundaki küp adedini gösterir.</text>\n  <rect x="340" y="55" width="320" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="500" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Görünümde Sütun Yüksekliği Kuralı</text>\n  <text x="360" y="110" font-size="11.5" fill="#334155">• Önden bakıldığında her dikey hizada</text>\n  <text x="372" y="130" font-size="11.5" font-weight="bold" fill="#1e40af">en büyük sayı kadar kare görünür:</text>\n  <text x="372" y="155" font-size="11.5" fill="#334155">Sol hiza: max(3, 1) = 3 kat</text>\n  <text x="372" y="178" font-size="11.5" fill="#334155">Sağ hiza: max(2, 1) = 2 kat</text>\n  <text x="500" y="210" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">Toplam Birim Küp = 3 + 2 + 1 + 1 = 7 küp</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
